// ── Types ──────────────────────────────────────────────────────────────────
interface RawTask { id: string; name: string; priority: number; needs_power: boolean; duration: number; isHighPriority: boolean }
interface ScheduledTask { id: number; time: string; name: string; needsPower: boolean; isHighPriority: boolean; status: 'Power Window' | 'Offline Window' | 'High Priority' | 'Pending' }
interface AreaSchedule { areaName: string; stage: number; outages: { start: number; end: number; label: string }[]; province?: string; municipality?: string; coords?: { lat: number; lng: number } }
interface PowerStatusResult { area: AreaSchedule; key: string; hasPower: boolean; nextOutage: string | null; nextRestore: string | null; minutesUntilChange: number | null }
interface Recommendation { key: string; areaName: string; stage: number; hasPower: boolean; outagesCount: number; powerOnHours: number; reason: string; score: number }
interface TaskHistory { id: string; date: string; fileName: string; taskCount: number; efficiency: number; areaName: string; tasks: RawTask[] }
interface WorkHours { start: number; end: number }
interface NearbyPlace {
  id: string; name: string; type: 'cafe'|'restaurant'|'coworking'|'mall'|'library'|'wifi'
  distance: number; travelMins: number; hasPower: boolean; rating: number; openNow: boolean
  address: string; wifi: boolean; amenities: string[]; reviewCount?: number; phone?: string; mapUrl?: string
}
interface SearchSuggestion { key: string; label: string; sublabel: string; type: 'city'|'suburb'|'municipality'|'province'|'area'; icon: string }

