// ── Helpers ────────────────────────────────────────────────────────────────
const fmt = (m: number) => `${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`
const getNow = () => { const n = new Date(); return n.getHours()*60+n.getMinutes() }

const getPowerStatus = (area: AreaSchedule) => {
  const now = getNow()
  const cur = area.outages.find(o => now>=o.start && now<o.end)
  if (cur) return { hasPower:false, nextOutage:null, nextRestore:fmt(cur.end), minutesUntilChange:cur.end-now }
  const up = area.outages.filter(o=>o.start>now).sort((a,b)=>a.start-b.start)
  if (up.length) return { hasPower:true, nextOutage:fmt(up[0].start), nextRestore:null, minutesUntilChange:up[0].start-now }
  return { hasPower:true, nextOutage:null, nextRestore:null, minutesUntilChange:null }
}

const getWeeklySchedule = (area: AreaSchedule) => {
  const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat']; const today=new Date()
  return Array.from({length:7},(_,i)=>{
    const d=new Date(today); d.setDate(today.getDate()+i)
    const offset=(i*30)%60
    const outages=area.outages.map(o=>({start:o.start+(i%2===0?0:offset),end:o.end+(i%2===0?0:offset),label:o.label}))
    return { dayName:days[d.getDay()], dateStr:d.toLocaleDateString('en-ZA',{day:'numeric',month:'short'}), isToday:i===0, outages, totalOffMins:outages.reduce((a,o)=>a+(o.end-o.start),0), stage:Math.min(8,area.stage+(i%3===2?1:0)) }
  })
}

const getRecommendations = (): Recommendation[] =>
  Object.entries(AREA_DATABASE).map(([key,area])=>{
    const s=getPowerStatus(area); const totalOff=area.outages.reduce((a,o)=>a+(o.end-o.start),0)
    const powerOnHours=Math.round(((1440-totalOff)/60)*10)/10
    let score=100-area.stage*10-area.outages.length*5
    if(s.hasPower) score+=15; if(s.minutesUntilChange&&s.minutesUntilChange>120) score+=10
    const reason=s.hasPower?(s.nextOutage?`Power on · next cut ${s.nextOutage}`:'No more outages today'):`Outage now · restores ${s.nextRestore}`
    return { key, areaName:area.areaName, stage:area.stage, hasPower:s.hasPower, outagesCount:area.outages.length, powerOnHours, reason, score }
  }).sort((a,b)=>b.score-a.score)

const scheduleTasksAroundOutages = (raw: RawTask[], outages: AreaSchedule['outages'], workStart: number): ScheduledTask[] => {
  // High-priority tasks scheduled first, then normal
  const sorted = [...raw].sort((a,b) => (b.isHighPriority?1:0)-(a.isHighPriority?1:0))
  const result: ScheduledTask[]=[]; let cursor=workStart
  for(const task of sorted){
    if(task.needs_power) for(const o of outages) if(cursor>=o.start&&cursor<o.end) cursor=o.end
    const end=cursor+task.duration; const duringOutage=outages.some(o=>cursor>=o.start&&cursor<o.end)
    let status: ScheduledTask['status']
    if(task.isHighPriority) status='High Priority'
    else if(!task.needs_power && duringOutage) status='Offline Window'
    else status='Power Window'
    result.push({ id:result.length+1, time:`${fmt(cursor)} – ${fmt(end)}`, name:task.name, needsPower:task.needs_power, isHighPriority:task.isHighPriority, status })
    cursor=end+5
  }
  return result
}

const parseCSV = (text: string): RawTask[] =>
  text.trim().split('\n').slice(1).map((line,i)=>{
    const c=line.split(',').map(s=>s.trim().replace(/"/g,''))
    if(c.length<4) return null
    return { id:`task-${i}-${Date.now()}`, name:c[0]||'Unnamed', priority:parseInt(c[1])||5, needs_power:c[2]?.toLowerCase()==='true', duration:parseInt(c[3])||30, isHighPriority:c[4]?.toLowerCase()==='true' }
  }).filter(Boolean) as RawTask[]

