// Search suggestions function
const getSearchSuggestions = (query: string): SearchSuggestion[] => {
  if (!query || query.length < 2) return []
  const q = query.toLowerCase().trim()
  return ALL_SA_AREAS.filter(area =>
    area.label.toLowerCase().includes(q) ||
    area.sublabel.toLowerCase().includes(q) ||
    area.key.toLowerCase().includes(q)
  ).slice(0, 8)
}

// Get nearby places for area key (with smart fallback)
const getNearbyForArea = (areaKey: string): NearbyPlace[] => {
  if (NEARBY_DB[areaKey]) return NEARBY_DB[areaKey]
  // Fallback: find in parent area DB
  const area = AREA_DATABASE[areaKey]
  if (!area) return NEARBY_DB['sandton']
  const province = area.province?.toLowerCase()
  if (province?.includes('western cape')) return NEARBY_DB['cape town']
  if (province?.includes('kwazulu')) return NEARBY_DB['durban']
  if (province?.includes('free state')) return NEARBY_DB['bloemfontein']
  if (province?.includes('limpopo')) return NEARBY_DB['polokwane']
  if (province?.includes('mpumalanga')) return NEARBY_DB['nelspruit']
  return NEARBY_DB['johannesburg']
}

// ══════════════════════════════════════════════════════════════════════════
// ── ML ENGINE — UNSUPERVISED: K-MEANS CLUSTERING ─────────────────────────
// ══════════════════════════════════════════════════════════════════════════
interface AreaFeatureVector { key: string; areaName: string; province: string; features: number[]; cluster?: number }
interface KMeansCluster { id: number; centroid: number[]; label: string; color: string; description: string; areas: AreaFeatureVector[] }

// Extract feature vectors from AREA_DATABASE:
// [stage, outageCount, totalOffMinutes, firstOutageStart, avgOutageDuration, powerOnRatio]
const buildAreaFeatures = (): AreaFeatureVector[] =>
  Object.entries(AREA_DATABASE).map(([key, area]) => {
    const totalOff = area.outages.reduce((a, o) => a + (o.end - o.start), 0)
    const avgDur = area.outages.length ? totalOff / area.outages.length : 0
    const firstStart = area.outages.length ? area.outages[0].start : 1440
    const powerOnRatio = (1440 - totalOff) / 1440
    return {
      key, areaName: area.areaName, province: area.province || 'Unknown',
      features: [
        area.stage / 8,                          // normalised stage
        area.outages.length / 4,                  // normalised outage count
        totalOff / 1440,                          // fraction of day off
        firstStart / 1440,                        // when first cut starts
        avgDur / 300,                             // normalised avg duration
        powerOnRatio,                             // power-on ratio
      ]
    }
  })

const euclidean = (a: number[], b: number[]) => Math.sqrt(a.reduce((s, v, i) => s + (v - b[i]) ** 2, 0))

const kMeans = (data: AreaFeatureVector[], k: number, maxIter = 100): KMeansCluster[] => {
  // Initialise centroids using k-means++ style seeding
  const centroids: number[][] = [data[Math.floor(Math.random() * data.length)].features.slice()]
  while (centroids.length < k) {
    const dists = data.map(d => Math.min(...centroids.map(c => euclidean(d.features, c))))
    const total = dists.reduce((a, b) => a + b, 0)
    let r = Math.random() * total
    for (let i = 0; i < data.length; i++) { r -= dists[i]; if (r <= 0) { centroids.push(data[i].features.slice()); break } }
  }

  let assignments = new Array(data.length).fill(0)
  for (let iter = 0; iter < maxIter; iter++) {
    // Assign each point to nearest centroid
    const newAssign = data.map(d => {
      let best = 0, bestDist = Infinity
      centroids.forEach((c, ci) => { const dist = euclidean(d.features, c); if (dist < bestDist) { bestDist = dist; best = ci } })
      return best
    })
    if (newAssign.every((a, i) => a === assignments[i])) break
    assignments = newAssign
    // Recompute centroids
    centroids.forEach((_, ci) => {
      const members = data.filter((_, i) => assignments[i] === ci)
      if (members.length === 0) return
      centroids[ci] = centroids[ci].map((_, fi) => members.reduce((s, d) => s + d.features[fi], 0) / members.length)
    })
  }

  const clusterMeta = [
    { label: 'Low Impact',    color: '#10b981', description: 'Stage 1–2 · short or infrequent cuts · best productivity zones' },
    { label: 'Medium Impact', color: '#f59e0b', description: 'Stage 2–3 · moderate disruption · plan power tasks carefully' },
    { label: 'High Impact',   color: '#f97316', description: 'Stage 3–4 · frequent cuts · prioritise offline tasks' },
    { label: 'Severe Impact', color: '#ef4444', description: 'Stage 4+ · majority of day offline · critical planning needed' },
  ]

  return centroids.map((centroid, ci) => {
    const members = data.filter((_, i) => assignments[i] === ci).map(d => ({ ...d, cluster: ci }))
    const avgStage = members.reduce((s, d) => s + d.features[0] * 8, 0) / (members.length || 1)
    const metaIdx = avgStage < 2 ? 0 : avgStage < 3 ? 1 : avgStage < 4 ? 2 : 3
    return { id: ci, centroid, ...clusterMeta[metaIdx], areas: members }
  }).sort((a, b) => a.centroid[0] - b.centroid[0])
}

// Run K-Means once at module level (deterministic enough with seed data)
const ML_AREA_FEATURES = buildAreaFeatures()
const runKMeans = () => kMeans(ML_AREA_FEATURES, 4)

// ══════════════════════════════════════════════════════════════════════════
// ── ML ENGINE — SUPERVISED: DECISION TREE CLASSIFIER ─────────────────────
// ── Predicts: hasPower (boolean) given [stage, timeOfDay, outageCount]  ──
// ══════════════════════════════════════════════════════════════════════════
interface DTNode { feature?: number; threshold?: number; left?: DTNode; right?: DTNode; prediction?: number; confidence?: number; samples?: number }
interface TrainingSample { features: number[]; label: number }

// Generate synthetic training data from AREA_DATABASE (ground-truth labels)
const generateTrainingData = (): TrainingSample[] => {
  const samples: TrainingSample[] = []
  // For each area × each 30-min slot in the day
  Object.values(AREA_DATABASE).forEach(area => {
    for (let t = 0; t < 1440; t += 30) {
      const inOutage = area.outages.some(o => t >= o.start && t < o.end) ? 1 : 0
      const totalOff = area.outages.reduce((a, o) => a + (o.end - o.start), 0)
      samples.push({
        features: [
          area.stage / 8,            // [0] stage normalised
          t / 1440,                  // [1] time of day normalised
          area.outages.length / 4,   // [2] outage count normalised
          totalOff / 1440,           // [3] total off-time fraction
        ],
        label: 1 - inOutage          // 1 = has power, 0 = no power
      })
    }
  })
  return samples
}

const gini = (labels: number[]): number => {
  if (!labels.length) return 0
  const p1 = labels.filter(l => l === 1).length / labels.length
  return 1 - p1 * p1 - (1 - p1) * (1 - p1)
}

const bestSplit = (samples: TrainingSample[], featureCount: number): { feature: number; threshold: number; gain: number } => {
  let bestGain = -Infinity, bestFeature = 0, bestThreshold = 0.5
  const parentGini = gini(samples.map(s => s.label))
  for (let f = 0; f < featureCount; f++) {
    const vals = [...new Set(samples.map(s => s.features[f]))].sort((a, b) => a - b)
    for (let vi = 0; vi < vals.length - 1; vi++) {
      const thresh = (vals[vi] + vals[vi + 1]) / 2
      const left = samples.filter(s => s.features[f] <= thresh)
      const right = samples.filter(s => s.features[f] > thresh)
      if (!left.length || !right.length) continue
      const gain = parentGini - (left.length / samples.length) * gini(left.map(s => s.label)) - (right.length / samples.length) * gini(right.map(s => s.label))
      if (gain > bestGain) { bestGain = gain; bestFeature = f; bestThreshold = thresh }
    }
  }
  return { feature: bestFeature, threshold: bestThreshold, gain: bestGain }
}

const buildTree = (samples: TrainingSample[], depth = 0, maxDepth = 5): DTNode => {
  const labels = samples.map(s => s.label)
  const ones = labels.filter(l => l === 1).length
  const prediction = ones >= samples.length / 2 ? 1 : 0
  const confidence = Math.max(ones, samples.length - ones) / samples.length
  if (depth >= maxDepth || new Set(labels).size === 1 || samples.length < 10)
    return { prediction, confidence, samples: samples.length }
  const { feature, threshold, gain } = bestSplit(samples, 4)
  if (gain <= 0) return { prediction, confidence, samples: samples.length }
  const left = samples.filter(s => s.features[feature] <= threshold)
  const right = samples.filter(s => s.features[feature] > threshold)
  return { feature, threshold, left: buildTree(left, depth + 1, maxDepth), right: buildTree(right, depth + 1, maxDepth) }
}

const predictTree = (node: DTNode, features: number[]): { prediction: number; confidence: number } => {
  if (node.prediction !== undefined) return { prediction: node.prediction, confidence: node.confidence ?? 1 }
  if (features[node.feature!] <= node.threshold!) return predictTree(node.left!, features)
  return predictTree(node.right!, features)
}

// Train the tree once at module level
const TRAINING_DATA = generateTrainingData()
const DECISION_TREE = buildTree(TRAINING_DATA)

const dtPredictPower = (stage: number, timeMinutes: number, outageCount: number, totalOffMins: number) =>
  predictTree(DECISION_TREE, [stage / 8, timeMinutes / 1440, outageCount / 4, totalOffMins / 1440])

// Evaluate tree accuracy on training data
const evaluateTree = () => {
  let correct = 0
  TRAINING_DATA.forEach(s => { const p = predictTree(DECISION_TREE, s.features); if (p.prediction === s.label) correct++ })
  return Math.round((correct / TRAINING_DATA.length) * 100)
}
const DT_ACCURACY = evaluateTree()

// ── ML Insights types ────────────────────────────────────────────────────
interface MLInsights { clusters: KMeansCluster[]; dtAccuracy: number; currentCluster: KMeansCluster | null }

