// ── SMART SEARCH BAR ───────────────────────────────────────────────────────
const SmartSearchBar: React.FC<{
  value: string; onChange: (v:string)=>void; onSelect: (key:string, label:string)=>void
  onSearch: ()=>void; loading: boolean; error: string; currentArea: AreaSchedule
}> = ({value, onChange, onSelect, onSearch, loading, error, currentArea}) => {
  const [open, setOpen] = useState(false)
  const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([])
  const [focused, setFocused] = useState(false)
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setSuggestions(getSearchSuggestions(value))
  }, [value])

  useEffect(() => {
    const handler = (e: MouseEvent) => { if(ref.current && !ref.current.contains(e.target as Node)) setOpen(false) }
    document.addEventListener('mousedown', handler)
    return ()=>document.removeEventListener('mousedown', handler)
  }, [])

  const typeColors: Record<string, string> = {
    city:'rgba(96,165,250,0.15)', suburb:'rgba(52,211,153,0.15)',
    municipality:'rgba(167,139,250,0.15)', province:'rgba(251,191,36,0.15)', area:'rgba(99,102,241,0.15)'
  }
  const typeTextColors: Record<string, string> = {
    city:'#60a5fa', suburb:'#34d399', municipality:'#a78bfa', province:'#fbbf24', area:'#818cf8'
  }

  const ps = getPowerStatus(currentArea)

  return (
    <div ref={ref} style={{position:'relative',maxWidth:420,flex:1}}>
      {/* Search input */}
      <div style={{position:'relative',display:'flex',alignItems:'center',background:focused?'rgba(255,255,255,0.07)':'rgba(255,255,255,0.04)',border:focused?'1px solid rgba(99,102,241,0.4)':'1px solid rgba(255,255,255,0.09)',borderRadius:14,transition:'all 0.2s',overflow:'hidden'}}>
        <Search size={13} style={{position:'absolute',left:13,color:'#64748b',flexShrink:0}}/>
        <input
          type="text"
          value={value}
          onChange={e=>{onChange(e.target.value); setOpen(true)}}
          onFocus={()=>{setFocused(true); setOpen(true)}}
          onBlur={()=>setFocused(false)}
          onKeyDown={e=>{ if(e.key==='Enter'){onSearch(); setOpen(false)} if(e.key==='Escape') setOpen(false) }}
          placeholder="Search any SA city, suburb, municipality…"
          style={{width:'100%',padding:'9px 12px 9px 34px',background:'transparent',border:'none',fontSize:12.5,color:'#f1f5f9',outline:'none',fontFamily:'inherit'}}
        />
        {loading&&<div style={{position:'absolute',right:40,width:14,height:14,border:'2px solid rgba(99,102,241,0.3)',borderTop:'2px solid #6366f1',borderRadius:'50%'}} className="loading-spin"/>}
        {value&&<button onClick={()=>{onChange(''); setOpen(false)}} style={{position:'absolute',right:10,color:'#475569',background:'none',border:'none',cursor:'pointer',padding:4,display:'flex',alignItems:'center'}}><X size={12}/></button>}
      </div>

      {/* Current location badge */}
      <div style={{position:'absolute',top:'calc(100% + 4px)',right:0,display:'flex',alignItems:'center',gap:4,background:'rgba(0,0,0,0.7)',border:'1px solid rgba(255,255,255,0.08)',borderRadius:20,padding:'3px 10px',fontSize:10,backdropFilter:'blur(10px)',pointerEvents:'none',zIndex:1}}>
        <span style={{width:5,height:5,borderRadius:'50%',background:ps.hasPower?'#10b981':'#ef4444',boxShadow:`0 0 4px ${ps.hasPower?'rgba(16,185,129,0.8)':'rgba(239,68,68,0.8)'}`}}/>
        <span style={{color:'#94a3b8'}}>{currentArea.areaName.split(',')[0]}</span>
        {currentArea.province&&<span style={{color:'#475569'}}>· {currentArea.province}</span>}
      </div>

      {/* Error */}
      {error&&<p style={{color:'#f87171',fontSize:11,marginTop:4,position:'absolute',top:'100%',left:0,background:'rgba(239,68,68,0.1)',border:'1px solid rgba(239,68,68,0.2)',borderRadius:8,padding:'4px 10px',whiteSpace:'nowrap'}}>{error}</p>}

      {/* Dropdown suggestions */}
      {open && suggestions.length > 0 && (
        <div className="search-dropdown" style={{position:'absolute',top:'calc(100% + 8px)',left:0,right:0,background:'rgba(12,12,22,0.98)',border:'1px solid rgba(255,255,255,0.1)',borderRadius:14,overflow:'hidden',zIndex:100,boxShadow:'0 20px 60px rgba(0,0,0,0.8)',backdropFilter:'blur(20px)'}}>
          <div style={{padding:'8px 12px 6px',borderBottom:'1px solid rgba(255,255,255,0.05)'}}>
            <p style={{fontSize:10,color:'#475569',fontWeight:600,textTransform:'uppercase',letterSpacing:'0.06em'}}>South Africa · {suggestions.length} results</p>
          </div>
          {suggestions.map((s,i)=>(
            <button
              key={s.key}
              className="suggestion-item"
              onMouseDown={()=>{ onSelect(s.key, s.label); onChange(s.label); setOpen(false) }}
              style={{width:'100%',display:'flex',alignItems:'center',gap:10,padding:'10px 14px',border:'none',background:'transparent',cursor:'pointer',borderBottom:i<suggestions.length-1?'1px solid rgba(255,255,255,0.04)':'none',transition:'background 0.15s'}}
            >
              <span style={{fontSize:18,flexShrink:0,width:24,textAlign:'center'}}>{s.icon}</span>
              <div style={{flex:1,textAlign:'left',minWidth:0}}>
                <p style={{color:'#f1f5f9',fontSize:13,fontWeight:500}}>{s.label}</p>
                <p style={{color:'#475569',fontSize:11,overflow:'hidden',whiteSpace:'nowrap',textOverflow:'ellipsis'}}>{s.sublabel}</p>
              </div>
              <span style={{background:typeColors[s.type]||typeColors.area,color:typeTextColors[s.type]||typeTextColors.area,padding:'2px 8px',borderRadius:20,fontSize:10,fontWeight:600,flexShrink:0,textTransform:'capitalize'}}>{s.type}</span>
            </button>
          ))}
          <div style={{padding:'8px 14px',borderTop:'1px solid rgba(255,255,255,0.05)',background:'rgba(99,102,241,0.04)'}}>
            <p style={{fontSize:10,color:'#334155'}}>⌨️ Type any SA city, suburb, or municipality · Press Enter to search</p>
          </div>
        </div>
      )}
    </div>
  )
}

