// ── AI PANEL ───────────────────────────────────────────────────────────────
const AIPanel: React.FC<{area:AreaSchedule;efficiency:number;tasks:ScheduledTask[];nearbyWithPower:NearbyPlace[]}> = ({area,efficiency,tasks,nearbyWithPower}) => {
  const ps=getPowerStatus(area)
  const [response,setResponse]=useState<string|null>(null)
  const [loading,setLoading]=useState(false)
  const [open,setOpen]=useState(false)

  const getAIInsight = async () => {
    setLoading(true); setOpen(true)
    const prompt=`You are LoadShed AI, a South African load shedding assistant. Briefly analyze this situation in 2-3 sentences with practical advice: Area: ${area.areaName}${area.province?', '+area.province:''}, Stage ${area.stage}, Power: ${ps.hasPower?'ON':'OFF'}${ps.nextOutage?`, next cut at ${ps.nextOutage}`:''}${ps.nextRestore?`, restores at ${ps.nextRestore}`:''}, Outages today: ${area.outages.map(o=>o.label).join(', ')||'None'}, Tasks efficiency: ${efficiency}%, ${nearbyWithPower.length} powered locations nearby. Be concise and specific for South Africa.`
    try {
      const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:1000,messages:[{role:'user',content:prompt}]})})
      const d=await r.json()
      setResponse(d.content?.[0]?.text||'Unable to generate insight at this time.')
    } catch { setResponse('Power up your planning: Based on current conditions, schedule high-priority tasks during power windows for maximum productivity.') }
    setLoading(false)
  }

  return (
    <div style={{background:'linear-gradient(135deg,rgba(99,102,241,0.06),rgba(139,92,246,0.04))',border:'1px solid rgba(99,102,241,0.15)',borderRadius:16,marginBottom:16,overflow:'hidden'}}>
      <button onClick={open?()=>setOpen(false):getAIInsight} className="w-full flex items-center justify-between p-4" style={{background:'none',border:'none',cursor:'pointer',color:'#f1f5f9'}}>
        <div className="flex items-center gap-2.5">
          <div style={{width:28,height:28,borderRadius:8,background:'linear-gradient(135deg,rgba(99,102,241,0.3),rgba(139,92,246,0.3))',display:'flex',alignItems:'center',justifyContent:'center'}}>
            <Sparkles size={14} style={{color:'#a78bfa'}}/>
          </div>
          <span style={{fontWeight:600,fontSize:13}}>AI Power Insight</span>
          {efficiency>0&&<span style={{background:'rgba(16,185,129,0.12)',color:'#34d399',padding:'2px 8px',borderRadius:20,fontSize:11}}>{efficiency}% efficient</span>}
        </div>
        {open?<ChevronUp size={14} style={{color:'#64748b'}}/>:<ChevronDown size={14} style={{color:'#64748b'}}/>}
      </button>
      {open&&(
        <div style={{borderTop:'1px solid rgba(99,102,241,0.1)',padding:'14px 16px'}}>
          {loading?<div className="flex items-center gap-3"><div style={{width:16,height:16,border:'2px solid rgba(99,102,241,0.3)',borderTop:'2px solid #6366f1',borderRadius:'50%'}} className="loading-spin"/><span style={{color:'#64748b',fontSize:13}}>Analyzing conditions for {area.areaName}…</span></div>
          :<p style={{color:'#94a3b8',fontSize:13,lineHeight:1.7}}>{response}</p>}
        </div>
      )}
    </div>
  )
}

