// ── PRODUCTIVITY CHART ─────────────────────────────────────────────────────
const ProductivityChart: React.FC<{history:TaskHistory[]}> = ({history}) => {
  if(history.length<2) return (
    <div style={{background:'rgba(255,255,255,0.02)',border:'1px solid rgba(255,255,255,0.07)',borderRadius:16,padding:'20px',textAlign:'center',paddingTop:56,paddingBottom:56}}>
      <BarChart2 size={28} style={{margin:'0 auto 12px',color:'#1e293b'}}/>
      <p style={{color:'#334155',fontSize:13}}>Generate at least 2 schedules to see your productivity trend</p>
    </div>
  )
  const data=[...history].reverse().slice(-7)
  const avg=Math.round(data.reduce((a,h)=>a+h.efficiency,0)/data.length)
  const trend=data[data.length-1].efficiency-data[0].efficiency
  const best=Math.max(...data.map(d=>d.efficiency))

  return (
    <div style={{background:'rgba(255,255,255,0.02)',border:'1px solid rgba(255,255,255,0.07)',borderRadius:16,padding:'20px',marginBottom:20}} className="fade-in-up">
      <div style={{display:'flex',alignItems:'center',justifyContent:'space-between',marginBottom:20}}>
        <div style={{display:'flex',alignItems:'center',gap:8}}><BarChart2 size={15} style={{color:'#a78bfa'}}/><h2 style={{fontSize:14,fontWeight:700}}>Productivity Analytics</h2></div>
        <div style={{display:'flex',alignItems:'center',gap:16,fontSize:12}}>
          <span style={{color:'#475569'}}>Avg <strong style={{color:'#f1f5f9'}}>{avg}%</strong></span>
          <span style={{color:trend>=0?'#10b981':'#ef4444',display:'flex',alignItems:'center',gap:4}}>{trend>=0?<TrendingUp size={11}/>:<TrendingDown size={11}/>}{Math.abs(trend)}% trend</span>
        </div>
      </div>
      <div style={{display:'flex',alignItems:'flex-end',gap:8,height:128,marginBottom:12}}>
        {data.map((entry,i)=>{
          const h=Math.max(8,(entry.efficiency/100)*100)
          const grad=entry.efficiency>=80?'linear-gradient(to top,#10b981,#34d399)':entry.efficiency>=60?'linear-gradient(to top,#f59e0b,#fbbf24)':'linear-gradient(to top,#ef4444,#f87171)'
          return (
            <div key={i} style={{flex:1,display:'flex',flexDirection:'column',alignItems:'center',gap:4}} className="group relative">
              <div style={{width:'100%',borderRadius:'4px 4px 0 0',background:grad,height:`${h}%`,transition:'height 0.5s ease'}}/>
              <span style={{color:'#334155',fontSize:10}}>{entry.date.split(',')[0]}</span>
            </div>
          )
        })}
      </div>
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:12,marginBottom:16}}>
        {[{label:'Best Session',val:`${best}%`,color:'#10b981'},{label:'Average',val:`${avg}%`,color:'#f1f5f9'},{label:'Sessions',val:`${data.length}`,color:'#a78bfa'}].map((s,i)=>(
          <div key={i} style={{background:'rgba(255,255,255,0.03)',border:'1px solid rgba(255,255,255,0.06)',borderRadius:12,padding:'12px',textAlign:'center'}}>
            <p style={{color:s.color,fontSize:18,fontWeight:800}}>{s.val}</p>
            <p style={{color:'#334155',fontSize:10,marginTop:2}}>{s.label}</p>
          </div>
        ))}
      </div>
      <div style={{borderTop:'1px solid rgba(255,255,255,0.05)',paddingTop:12}}>
        <p style={{fontSize:10,color:'#334155',marginBottom:8,display:'flex',alignItems:'center',gap:4}}><Sparkles size={10} style={{color:'#818cf8'}}/>AI Efficiency Tips</p>
        {['Schedule power tasks 1–2h after restoration to avoid instability windows.','Batch online syncing into one block to maximise offline focus time.','Your highest efficiency sessions happened in the morning — use that window.'].map((tip,i)=>(
          <div key={i} style={{display:'flex',alignItems:'flex-start',gap:6,marginBottom:6,fontSize:12,color:'#475569'}}><span style={{color:'#6366f1',flexShrink:0}}>→</span>{tip}</div>
        ))}
      </div>
    </div>
  )
}

